using System;
using System.IO;
using System.Linq;
using IdleIntelligence.Core;
using NUnit.Framework;
using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable]public sealed class SignalCase{public string name,action,id;public double at,random,quality,interval,factor,componentsEarned,dropsClaimed,regularCredits,regularData;public int draws;public bool active;public StateData before;public SignalState expected;public long[] components;public ItemInstance[] inventory;public bool[] known;public long fragments,nextId;public NumberData credits,data,eligible,entitlement;}
 [Serializable]public sealed class SignalFactorGuard{public double factor;public bool valid;}
 [Serializable]public sealed class SignalCases{public SignalCase[] cases;public SignalFactorGuard[] guards;}
 public sealed class SignalTests
 {
  static void Near(ScientificNumber a,NumberData expected,string label){var e=ScientificNumber.FromData(expected);if(e.IsZero)Assert.That(a.IsZero,Is.True,label);else Assert.That(a.Log10(),Is.EqualTo(e.Log10()).Within(2e-10),label);}
  [Test]public void SignalSpawnsClaimsFrozenFactorsAndRealEffectsMatchTypeScript()
  {
   var f=JsonUtility.FromJson<SignalCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/SignalReferenceCases.json")));Assert.That(f.cases.Length,Is.GreaterThanOrEqualTo(213));foreach(var guard in f.guards){var value=Game.New(1000000);value.Signals.visible=new[]{new LootSignal{id="factor-validation",spawnedAt=value.SavedAt,expiresAt=value.SavedAt+12000,x=20,y=20,hasRewardFactor=true,rewardFactor=guard.factor}};if(guard.valid)Assert.DoesNotThrow(()=>Game.Validate(value),"source accepted factor "+guard.factor);else Assert.Throws<FormatException>(()=>Game.Validate(value),"source rejected factor "+guard.factor);}foreach(var c in f.cases){var s=c.before.ToState();string original=JsonUtility.ToJson(StateData.From(s));int draws=0;Func<double> rng=()=>{draws++;return c.random;};var n=s;switch(c.action){case "claim":n=Signals.Claim(s,c.id,rng);break;case "advance":n=Game.Advance(s,c.at,c.active);break;case "reset":n=PrestigeRules.Reset(s);break;case "start":n=ChallengeRules.Start(s,"no-taps",1,"signals-test");break;case "abort":n=ChallengeRules.Return(s,false);break;}Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(original),c.name+" pure");Assert.That(JsonUtility.ToJson(n.Signals),Is.EqualTo(JsonUtility.ToJson(c.expected)),c.name+" spawn/progress/frozen factor");if(c.action=="claim")Assert.That(draws,Is.EqualTo(c.draws),c.name+" exact random draw sequence / no duplicate draw");Assert.That(n.Workshop.components,Is.EqualTo(c.components),c.name+" components");Assert.That(n.Workshop.fragments,Is.EqualTo(c.fragments),c.name+" blueprint fragments");Assert.That(n.Workshop.knownBlueprints,Is.EqualTo(c.known),c.name+" discovered blueprints");Assert.That(JsonUtility.ToJson(new SeasonTests.ItemList{items=n.Workshop.inventory}),Is.EqualTo(JsonUtility.ToJson(new SeasonTests.ItemList{items=c.inventory})),c.name+" item pool");Assert.That(n.Workshop.nextId,Is.EqualTo(c.nextId),c.name+" shared IDs");Assert.That(n.Lifetime.componentsEarned,Is.EqualTo(c.componentsEarned).Within(1e-7),c.name+" component producer");Assert.That(n.Lifetime.dropsClaimed,Is.EqualTo(c.dropsClaimed),c.name+" mission producer");Assert.That(n.Lifetime.regularCredits,Is.EqualTo(c.regularCredits).Within(Math.Max(1e-7,Math.Abs(c.regularCredits)*1e-12)),c.name+" regular production excludes drops");Assert.That(n.Lifetime.regularData,Is.EqualTo(c.regularData).Within(Math.Max(1e-7,Math.Abs(c.regularData)*1e-12)),c.name+" regular data excludes drops");Near(n.Credits,c.credits,c.name+" credits");Near(n.Data,c.data,c.name+" data");Near(n.Prestige.Eligible,c.eligible,c.name+" INT-eligible drop income");Near(n.Prestige.Entitlement,c.entitlement,c.name+" INT entitlement");Assert.That(Signals.Quality(n),Is.EqualTo(c.quality).Within(1e-10),c.name+" actual drop research/items");Assert.That(Signals.Interval(n),Is.EqualTo(c.interval).Within(1e-10),c.name+" interval");Assert.That(Signals.RewardFactor(n),Is.EqualTo(c.factor).Within(1e-10),c.name+" compensation");Game.Validate(n);Assert.That(JsonUtility.ToJson(StateData.From(n).ToState().Signals),Is.EqualTo(JsonUtility.ToJson(n.Signals)),c.name+" reload");}
  }
 }
}
